for n, f in [("DV", "DejaVuSans.ttf"), ("DV-B", "DejaVuSans-Bold.ttf"), ("DV-I", "DejaVuSans-Oblique.ttf")]:
    pdfmetrics.registerFont(TTFont(n, os.path.join(fd, f)))
pdfmetrics.registerFontFamily("DV", normal="DV", bold="DV-B", italic="DV-I", boldItalic="DV-B")
body = ParagraphStyle("b", fontName="DV", fontSize=9, leading=12.6, alignment=TA_JUSTIFY, spaceAfter=5)
h1 = ParagraphStyle("h1", fontName="DV-B", fontSize=14, leading=18, spaceBefore=10, spaceAfter=6, textColor=colors.HexColor("#1F3A5F"))
h2 = ParagraphStyle("h2", fontName="DV-B", fontSize=11, leading=14, spaceBefore=8, spaceAfter=4, textColor=colors.HexColor("#1F3A5F"))
small = ParagraphStyle("s", fontName="DV", fontSize=7.5, leading=10, spaceAfter=3)
cap = ParagraphStyle("c", fontName="DV-I", fontSize=8, leading=10, spaceAfter=6)
P = lambda t, st=body: Paragraph(t, st)
f3 = lambda x: f"{x:.3f}"; f2 = lambda x: f"{x:.2f}"; f1 = lambda x: f"{x:.1f}"
pc = lambda x: f"{100*x:.1f}%"           # fraction -> percent
def nice(s): return s.replace("_", " ").replace("DM", "DM").strip()
def tbl(data, widths=None, fs=7.5, hdr=True, zebra=True):
    t = Table([[Paragraph(str(c), ParagraphStyle("t", fontName="DV", fontSize=fs, leading=fs + 2)) for c in r] for r in data], colWidths=widths, repeatRows=1 if hdr else 0)
    st = [("GRID", (0, 0), (-1, -1), .3, colors.grey), ("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#DCE6F2"))]
    t.setStyle(TableStyle(st)); return t
def img(path, w=15 * cm):
    from PIL import Image as PI
    iw, ih = PI.open(path).size; return Image(path, width=w, height=w * ih / iw)
wc = lambda t: len(re.sub(r"<[^>]+>", "", t).split())

p1 = R["part1"]; s21 = R["s21"]; s22 = R["s22_key"]; s23 = R["s23"]; cal = R["s23_calib"]; crit = R["s23_crit"]; mech = R["s23_mech"]
sw = {round(r["t"], 2): r for r in R["s24_sweep"]}; r35 = R["s24_t035"]; gs = R["s24_group_sizes"]; pair = R["s24_pairs_opposite"][0]
ex_f, ex_m = R["s24_examples"]
cm_ = p1["confusion"]
def row22(name): return next(r for r in s22 if r["predictor"] == name)
