S = []   # story
S += [P("CSET485 – AI and Society · Assignment 1", ParagraphStyle("t", fontName="DV-B", fontSize=18, leading=22, textColor=colors.HexColor("#1F3A5F"))),
      P("Stress-testing a credit-approval model on the German Credit dataset", h2),
      P(f"Roll number ending 0113 → last digit 3 → <b>German Credit (Statlog)</b>; random_state = <b>113</b>; 70/30 split (train n = {R['n_train']}, test n = {R['n_test']}). Target: approval (1 = good credit / approve, 0 = reject); base rate {pc(R['base_rate_approve'])}. "
        "All numbers below are produced by the accompanying notebook (<i>CSET485_Assignment1_GermanCredit.ipynb</i>) and stored in <i>results.json</i>; this PDF is generated from that file.")]
S += [P("<b>Data note.</b> The UCI archive was not reachable from my build environment, so the same 1,000-row Statlog data was loaded from a GitHub mirror (labels decoded from the A11/A12… codes; category counts such as 548/310/92/50 for personal_status_sex match the UCI file). "
        "<b>Label convention.</b> The brief calls the flagged class 'high risk'. Because the modelled outcome here is <i>approval</i>, 'flagged / high' below means 'score ≥ cut-off' = predicted approve, for both thresholding rules. "
        "<b>Sensitive variable.</b> 'Sex' is derived from personal_status_sex (female = 'female : divorced/separated/married', n = 310; male = the three male categories, n = 690); the dataset has no 'single female' category, so sex and marital status are entangled.", small)]

# ---------------- preprocessing
S += [P("Data preprocessing", h1)]
pooled = R["pooled_rare_levels"]
S += [P(f"<b>Missing values.</b> {R['missing_values_total']} NaNs and {R['placeholder_cells']} placeholder cells ('?', 'NA', blanks) in all 1,000 × 21 cells, so no imputation was needed. "
        f"<b>Categorical encoding.</b> {R['n_categorical']} categorical attributes were one-hot encoded. Rare levels (&lt;30 rows) were pooled into 'rare_levels' (purpose: education, repairs, furniture/equipment, business; job: unemployed/non-resident), and the reference level of each attribute is its <i>most frequent</i> level. "
        "This is a deliberate fix: with alphabetical reference coding, the reference 'purpose = business' (9 rows, 6 of them in the training split, all approved), causing complete separation (logit failed to converge, constant ≈ +20). After the fix the logit converges with all |coef| &lt; 3. "
        f"This gives {R['n_features']} features. "
        f"<b>Feature scaling.</b> The 7 numeric attributes were z-scored with a scaler fitted on the training split only (no leakage), so numeric coefficients are per 1 SD. "
        f"<b>Outliers.</b> 1.5×IQR flags {R['iqr_outliers']['duration']} loans on duration, {R['iqr_outliers']['amount']} on amount and {R['iqr_outliers']['age']} on age. Loan amount is right-skewed (skewness {f2(R['amount_skew_raw'])}); a log transform reduces this to {f2(R['amount_skew_log'])}. "
        "No rows were removed: the extreme values are genuine large/long loans, and n is small. The split is not stratified (the brief does not require it).")]

# ---------------- Part 1
S += [P("Part 1 — Build: Model A (OLS) vs Model B (logistic)", h1)]
S += [P(f"Both models were fit on the training split and evaluated on the test split. Model A's predictions are cut at their test-set <b>median = {f3(p1['median_ols'])}</b>; Model B's at <b>0.5</b>. "
        f"OLS predictions range from {f3(p1['ols_min'])} to {f3(p1['ols_max'])}; {p1['ols_outside_01']} of {R['n_test']} ({f1(100*p1['ols_outside_01']/R['n_test'])}%) fall outside [0, 1].")]
ctab = [["", "B: Logit &lt; 0.5 (low)", "B: Logit ≥ 0.5 (flagged)", "Row total"],
        ["A: OLS &lt; median (low)", cm_[0][0], cm_[0][1], sum(cm_[0])], ["A: OLS ≥ median (flagged)", cm_[1][0], cm_[1][1], sum(cm_[1])],
        ["Column total", cm_[0][0] + cm_[1][0], cm_[0][1] + cm_[1][1], R["n_test"]]]
